"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { Activity, ArrowDownLeft, ArrowDownToLine, ArrowLeft, ArrowUpLeft, Bell, Boxes, Check, CheckCheck, ChevronLeft, CircleHelp, Clock3, Download, Factory, Fingerprint, FlaskConical, Gem, History, LayoutDashboard, Link2, Loader2, Menu, Package, Plus, Radio, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Timer, TriangleAlert, Users, Wrench, X } from "lucide-react";
import { applyCommand, collections, createSeed, fine, massBalance, metalName, stages, type Asset, type Batch, type Command, type Log, type Metal, type Product, type Workspace } from "@/lib/erp";

type Page = "dashboard" | "batches" | "inventory" | "assets" | "products" | "team" | "reports" | "connections";
type Modal = { kind: string; id?: string } | null;
const nav: { id: Page; label: string; icon: typeof Factory; group: string }[] = [
  { id: "dashboard", label: "اتاق فرمان", icon: LayoutDashboard, group: "نمای کلی" },
  { id: "batches", label: "تولید و بچ‌ها", icon: Factory, group: "عملیات کارخانه" },
  { id: "inventory", label: "انبار و مواد", icon: Boxes, group: "" },
  { id: "assets", label: "ابزار و تجهیزات", icon: Wrench, group: "" },
  { id: "products", label: "هویت محصول", icon: Fingerprint, group: "" },
  { id: "team", label: "تیم و نقش‌ها", icon: Users, group: "مدیریت" },
  { id: "reports", label: "گزارش و تراز", icon: Activity, group: "" },
  { id: "connections", label: "اتصال‌ها", icon: Settings2, group: "" },
];
const n = (value: number, digits = 2) => new Intl.NumberFormat("fa-IR", { maximumFractionDigits: digits }).format(value);
const time = (value: string) => new Intl.DateTimeFormat("fa-IR", { hour: "2-digit", minute: "2-digit", timeZone: "Asia/Tehran" }).format(new Date(value));
const date = (value: string) => new Intl.DateTimeFormat("fa-IR", { month: "short", day: "numeric", timeZone: "Asia/Tehran" }).format(new Date(value));
const duration = (start: string, end?: string) => { const m = Math.max(0, Math.floor((new Date(end || Date.now()).getTime() - new Date(start).getTime()) / 60000)); return `${n(Math.floor(m / 60))}:${String(m % 60).padStart(2, "0").replace(/\d/g, d => "۰۱۲۳۴۵۶۷۸۹"[+d])}`; };
const match = (query: string, ...values: unknown[]) => values.join(" ").toLocaleLowerCase().includes(query.toLocaleLowerCase().trim());

function Badge({ children, tone = "green" }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function MetalDot({ metal }: { metal: Metal }) { return <span className={`metal-dot ${metal}`}>{metal === "gold" ? "Au" : "Ag"}</span>; }
function Empty({ title = "هنوز رکوردی ثبت نشده", text = "با ثبت اولین عملیات، اطلاعات این بخش نمایش داده می‌شود." }: { title?: string; text?: string }) { return <div className="empty"><Boxes size={29} /><strong>{title}</strong><p>{text}</p></div>; }
function Field({ label, children, wide = false, hint }: { label: string; children: ReactNode; wide?: boolean; hint?: string }) { return <label className={`field ${wide ? "wide" : ""}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }

function Dialog({ title, subtitle, wide, onClose, children }: { title: string; subtitle?: string; wide?: boolean; onClose: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement;
    const overflow = document.body.style.overflow; document.body.style.overflow = "hidden";
    ref.current?.focus();
    const key = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "Tab") {
        const elements = ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input, select, textarea, a[href], [tabindex="0"]');
        if (!elements?.length) return;
        const first = elements[0], last = elements[elements.length - 1];
        if (e.shiftKey && (document.activeElement === first || document.activeElement === ref.current)) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };
    document.addEventListener("keydown", key);
    return () => { document.body.style.overflow = overflow; document.removeEventListener("keydown", key); previous?.focus(); };
  }, [onClose]);
  return <div className="modal-shade" onClick={e => { if (e.target === e.currentTarget) onClose(); }}><div className={`dialog ${wide ? "dialog-wide" : ""}`} role="dialog" aria-modal="true" aria-labelledby="dialog-title" ref={ref} tabIndex={-1}><header className="dialog-head"><div><h2 id="dialog-title">{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-btn" aria-label="بستن پنجره" onClick={onClose}><X size={20} /></button></header>{children}</div></div>;
}

function csv(name: string, rows: unknown[][]) {
  const clean = (value: unknown) => { let s = String(value ?? ""); if (/^[=+@\-\t\r]/.test(s)) s = "'" + s; return '"' + s.replaceAll('"', '""') + '"'; };
  const blob = new Blob(["\ufeff" + rows.map(row => row.map(clean).join(",")).join("\r\n")], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob), a = document.createElement("a"); a.href = url; a.download = name; a.click(); URL.revokeObjectURL(url);
}

export default function ERPApp() {
  const [state, setState] = useState<Workspace>(createSeed), [revision, setRevision] = useState(0);
  const [mode, setMode] = useState<"loading" | "cloud" | "preview" | "error">("loading"), [loadError, setLoadError] = useState("");
  const [page, setPage] = useState<Page>("dashboard"), [modal, setModal] = useState<Modal>(null);
  const [search, setSearch] = useState(""), [filter, setFilter] = useState("همه"), [mobile, setMobile] = useState(false);
  const [toast, setToast] = useState<{ text: string; error?: boolean } | null>(null), [busy, setBusy] = useState(false);
  const [, tick] = useState(0);
  const notify = useCallback((text: string, error = false) => setToast({ text, error }), []);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 6000); return () => clearTimeout(t); }, [toast]);
  useEffect(() => { const t = setInterval(() => tick(x => x + 1), 60000); return () => clearInterval(t); }, []);
  const sync = useCallback(async () => {
    try {
      const response = await fetch("/api/workspace", { cache: "no-store" });
      if (response.status === 401) { setMode("preview"); return; }
      const data = await response.json() as { state: Workspace; revision: number; error?: string };
      if (!response.ok) throw new Error(data.error || "دریافت اطلاعات انجام نشد.");
      setState(data.state); setRevision(data.revision); setMode("cloud"); setLoadError("");
    } catch (e) { setMode("error"); setLoadError(e instanceof Error ? e.message : "اتصال برقرار نشد."); }
  }, []);
  useEffect(() => { sync(); const focus = () => sync(); window.addEventListener("focus", focus); return () => window.removeEventListener("focus", focus); }, [sync]);
  useEffect(() => {
    const handler = () => { const p = window.location.hash.slice(1); if (nav.some(x => x.id === p)) { setPage(p as Page); setFilter("همه"); } };
    handler(); window.addEventListener("hashchange", handler); return () => window.removeEventListener("hashchange", handler);
  }, []);
  const go = (p: Page) => { setPage(p); setFilter("همه"); setSearch(""); setMobile(false); window.location.hash = p; };
  const close = useCallback(() => setModal(null), []);
  const open = (kind: string, id?: string) => setModal({ kind, id });
  async function send(command: Command) {
    if (busy) return false;
    if (mode === "loading" || mode === "error") { notify("ابتدا اتصال و همگام‌سازی اطلاعات را بررسی کن.", true); return false; }
    setBusy(true);
    try {
      if (mode === "preview") {
        const result = applyCommand(state, command); setState(result.state); notify(result.message + " · پیش‌نمایش بدون ذخیره");
      } else {
        const response = await fetch("/api/workspace", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision, command }) });
        const result = await response.json() as { state: Workspace; revision: number; message: string; error?: string; conflict?: boolean };
        if (!response.ok) { if (result.conflict) await sync(); throw new Error(result.error || "ثبت انجام نشد."); }
        setState(result.state); setRevision(result.revision); notify(result.message);
      }
      return true;
    } catch (e) { notify(e instanceof Error ? e.message : "ثبت انجام نشد.", true); return false; }
    finally { setBusy(false); }
  }
  const active = state.batches.filter(b => b.stage < 5), low = state.inventory.filter(i => i.quantity < i.minimum), activePeople = state.batches.flatMap(b => b.sessions.filter(s => !s.end));
  const selectedBatch = modal?.id ? state.batches.find(b => b.id === modal.id) : undefined;
  const selectedAsset = modal?.id ? state.assets.find(a => a.id === modal.id) : undefined;
  const selectedProduct = modal?.id ? state.products.find(p => p.id === modal.id) : undefined;
  const title = nav.find(x => x.id === page)!.label;

  const batchTable = (batches: Batch[]) => <div className="table-scroll"><table><thead><tr><th>شناسه و فلز</th><th>مالک / مبدأ</th><th>وزن ورودی</th><th>عیار</th><th>مرحلهٔ فعلی</th><th>افراد فعال</th><th aria-label="مشاهده" /></tr></thead><tbody>{batches.map(b => <tr key={b.id}><td><button className="table-id" onClick={() => open("batch", b.id)}><MetalDot metal={b.metal} /><span><b dir="ltr">{b.id}</b><small>{metalName(b.metal)} {b.priority === "فوری" && <em>فوری</em>}</small></span></button></td><td><span className="truncate">{b.owner}</span><small>{b.source}</small></td><td><b className="numeric">{n(b.weight / 1000, 3)}</b> <span className="muted">کیلوگرم</span></td><td><span className="mono">{b.assay.toFixed(1)}</span></td><td><Badge tone={b.stage === 5 ? "green" : b.stage === 4 ? "amber" : "blue"}>{b.stage < 5 && <i className="status-dot" />}{stages[b.stage]}</Badge></td><td><div className="avatar-stack">{b.sessions.filter(s => !s.end).map(s => { const p = state.operators.find(o => o.id === s.operatorId); return <span className="mini-avatar" key={s.id} title={p?.name}>{p?.initials}</span>; })}{!b.sessions.some(s => !s.end) && <span className="muted">—</span>}</div></td><td><button className="icon-btn" aria-label={`پرونده ${b.id}`} onClick={() => open("batch", b.id)}><ArrowLeft size={17} /></button></td></tr>)}</tbody></table>{!batches.length && <Empty title="بچی با این مشخصات پیدا نشد" text="فیلتر را تغییر بده یا یک محمولهٔ جدید ثبت کن." />}</div>;
  const eventList = (logs: Log[], limit = 5) => <div className="event-list">{logs.slice(0, limit).map(l => <button className="event" key={l.id} onClick={() => l.batchId ? open("batch", l.batchId) : go(l.type === "asset" ? "assets" : "inventory")}><span className={`event-icon ${l.type}`}>{l.type === "warning" ? <TriangleAlert size={16} /> : l.type === "product" ? <Fingerprint size={16} /> : l.type === "asset" ? <Wrench size={16} /> : <Activity size={16} />}</span><span><p>{l.text}</p><small>{date(l.time)}، {time(l.time)} · {l.actor}</small></span><ChevronLeft size={15} /></button>)}{!logs.length && <Empty />}</div>;

  return <div className="app-shell">
    {mobile && <div className="nav-shade" onClick={() => setMobile(false)} />}
    <aside className={`sidebar ${mobile ? "is-open" : ""}`}>
      <a href="#dashboard" className="brand" onClick={() => go("dashboard")}><div className="monogram">M<span>✦</span></div><div><b>MORIYATI</b><span>OPERATIONS SYSTEM</span></div></a>
      <div className="workspace-card"><span className="workspace-icon"><Factory size={18} /></span><div><b>کارخانه موریاتی</b><small>پالایش و تولید فلزات گرانبها</small></div><span className="online-dot" /></div>
      <nav aria-label="بخش‌های سامانه">{nav.map(item => <div key={item.id}>{item.group && <p className="nav-group">{item.group}</p>}<button className={`nav-item ${page === item.id ? "selected" : ""}`} onClick={() => go(item.id)}><item.icon size={19} /><span>{item.label}</span>{item.id === "batches" && <span className="nav-count">{n(active.length)}</span>}{item.id === "inventory" && low.length > 0 && <span className="nav-alert" />}</button></div>)}</nav>
      <div className="sidebar-bottom"><div className="edition"><span className="edition-dot" />نسخهٔ آزمایشی <span className="mono">v0.1</span></div><div className="profile"><span className="profile-avatar">AM</span><div><b>علیرضا مهربان</b><small>فضای شخصی مدیر سامانه</small></div><ShieldCheck size={17} /></div></div>
    </aside>

    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-btn mobile-menu" aria-label="باز کردن منو" onClick={() => setMobile(!mobile)}><Menu size={21} /></button><span>موریاتی</span><ChevronLeft size={13} /><b>{title}</b></div><div className="topbar-actions"><label className="global-search"><Search size={17} /><input placeholder="جست‌وجوی بچ، سریال، ابزار..." aria-label="جست‌وجوی سراسری" value={search} onChange={e => setSearch(e.target.value)} /><kbd>⌕</kbd></label><button className="icon-btn notifications" aria-label="هشدارهای موجودی" onClick={() => open("alerts")}><Bell size={19} />{low.length > 0 && <i />}</button><span className="topbar-divider" /><span className="top-avatar">AM</span></div></header>
    <main>
      <div className={`sample-notice ${mode === "error" ? "notice-error" : ""}`}><span><FlaskConical size={15} /><b>محیط آزمایشی</b><span className="notice-detail">تمام اعداد، موجودی‌ها و اپراتورها نمونه‌اند.</span></span><button onClick={() => sync()} title="همگام‌سازی مجدد"><span className={`sync-dot ${mode}`} />{mode === "cloud" ? "ذخیره در فضای خصوصی" : mode === "loading" ? "در حال اتصال..." : mode === "preview" ? "پیش‌نمایش بدون ذخیره" : "خطای اتصال؛ تلاش دوباره"}<RefreshCw size={13} /></button></div>
      {mode === "error" && <div className="error-box">{loadError} تغییرات تا برقراری اتصال ثبت نمی‌شوند.</div>}
      {!!search.trim() && <section className="search-results panel"><div className="panel-heading"><h2>نتایج جست‌وجو برای «{search}»</h2><button className="text-button" onClick={() => setSearch("")}>پاک کردن <X size={15} /></button></div>{[...state.batches.filter(b => match(search, b.id, b.owner, b.source)).map(b => ({ id: b.id, label: `${b.id} · ${metalName(b.metal)} · ${b.owner}`, kind: "batch" })), ...state.assets.filter(a => match(search, a.name, a.id, a.tag)).map(a => ({ id: a.id, label: `${a.name} · ${a.tag}`, kind: "asset" })), ...state.products.filter(p => match(search, p.serial, p.packaging, p.nfc)).map(p => ({ id: p.id, label: `${p.serial} · ${p.collection}`, kind: "product" }))].slice(0, 12).map(r => <button className="search-result" key={r.id} onClick={() => { open(r.kind, r.id); setSearch(""); }}><Search size={15} />{r.label}<ArrowLeft size={16} /></button>)}{!state.batches.some(b => match(search, b.id, b.owner, b.source)) && !state.assets.some(a => match(search, a.name, a.id, a.tag)) && !state.products.some(p => match(search, p.serial, p.packaging, p.nfc)) && <Empty title="نتیجه‌ای پیدا نشد" text="شناسه، سریال یا نام دیگری را امتحان کن." />}</section>}

      <div className="page-heading"><div><div className="eyebrow">MORIYATI <span>/</span> {page === "dashboard" ? "FACTORY OVERVIEW" : page.toUpperCase()}</div><h1>{page === "dashboard" ? "نبض کارخانه، در یک نگاه." : title}</h1><p>{({ dashboard: "از ورود محموله تا آخرین سریال؛ جریان کار را دنبال کن.", batches: "هر بچ، یک پرونده؛ هر مرحله، یک سابقهٔ روشن.", inventory: "فلز، مواد شیمیایی و ملزومات؛ تمام گردش‌ها در یک جا.", assets: "شناسنامه، کارکرد و چرخهٔ عمر هر ابزار را ببین.", products: "هویت ماندگار هر محصول، از بچ تولید تا بسته‌بندی.", team: "چه کسی، کجا، روی کدام بچ کار می‌کند؟", reports: "تراز هر بچ بر اساس وزن فلز خالص؛ طلا و نقره به‌صورت مستقل.", connections: "وضعیت اتصال سرویس‌ها و مسیر توسعهٔ سامانه." })[page]}</p></div><div className="heading-actions">{page === "dashboard" && <span className="today" suppressHydrationWarning>{new Intl.DateTimeFormat("fa-IR", { day: "numeric", month: "long", year: "numeric", timeZone: "Asia/Tehran" }).format(new Date())}</span>}{["dashboard", "batches"].includes(page) && <button className="button primary" onClick={() => open("create_batch")}><Plus size={17} />دریافت محموله</button>}{page === "inventory" && <button className="button primary" onClick={() => open("inventory_move")}><Plus size={17} />ثبت گردش</button>}{page === "assets" && <button className="button primary" onClick={() => open("create_asset")}><Plus size={17} />ابزار جدید</button>}{page === "products" && <button className="button primary" onClick={() => open("create_product")}><Plus size={17} />ثبت محصول</button>}{page === "team" && <button className="button primary" onClick={() => open("create_operator")}><Plus size={17} />افزودن همکار</button>}{page === "reports" && <button className="button secondary" onClick={() => csv("moriyati-batch-balance.csv", [["بچ", "فلز", "مرحله", "ورودی خالص گرم", "خروجی خالص گرم", "قابل بازیافت گرم", "اختلاف گرم"], ...state.batches.map(b => { const x = massBalance(b); return [b.id, metalName(b.metal), stages[b.stage], x.incoming, b.stage === 5 ? x.outgoing : "در جریان", b.recoverable ?? "", b.stage === 5 ? x.difference : ""]; })])}><Download size={16} />خروجی CSV</button>}</div></div>

      {page === "dashboard" && <>
        <div className="stats-grid"><Stat label="بچ‌های در جریان" value={n(active.length)} unit="بچ" icon={<Factory size={19} />} note={`${n(state.batches.filter(b => b.stage === 5).length)} بچ تکمیل‌شده`} onClick={() => go("batches")} /><Stat label="نقره در جریان تولید" value={n(active.filter(b => b.metal === "silver").reduce((s, b) => s + fine(b.weight, b.assay), 0) / 1000, 3)} unit="کیلوگرم" icon={<Gem size={19} />} note="بر مبنای فلز خالص" onClick={() => go("reports")} /><Stat label="طلا در جریان تولید" value={n(active.filter(b => b.metal === "gold").reduce((s, b) => s + fine(b.weight, b.assay), 0), 1)} unit="گرم" icon={<Gem size={19} />} note="بر مبنای فلز خالص" gold onClick={() => go("reports")} /><Stat label="افراد مشغول به کار" value={n(activePeople.length)} unit="نفر" icon={<Users size={19} />} note={`از ${n(state.operators.length)} همکار ثبت‌شده`} onClick={() => go("team")} /></div>
        <div className="dashboard-middle"><section className="panel production-panel"><div className="panel-heading"><div><h2>جریان تولید</h2><p>توزیع بچ‌های فعال در ایستگاه‌های کارخانه</p></div><Badge><i className="status-dot" />{n(active.length)} بچ فعال</Badge></div><div className="production-flow">{stages.slice(0, 5).map((s, i) => { const count = active.filter(b => b.stage === i).length; const Icon = [ArrowDownToLine, FlaskConical, Radio, Factory, ShieldCheck][i]; return <button key={s} className={`flow-step ${count ? "has-work" : ""}`} onClick={() => { go("batches"); setFilter(s); }}><span className="flow-icon"><Icon size={22} />{count > 0 && <i />}</span><strong>{n(count)}</strong><span>{s}</span><small>{count ? "بچ در این مرحله" : "آمادهٔ پذیرش"}</small></button>; })}</div><div className="production-footer"><span><span className="legend-dot" />ایستگاه دارای بچ</span><button className="text-button" onClick={() => go("batches")}>مشاهدهٔ تمام بچ‌ها <ArrowLeft size={15} /></button></div></section><section className="trace-card"><div className="trace-card-top"><Fingerprint size={25} /><span>THE MORIYATI STANDARD</span></div><h2>هر گرم،<br />قابل ردیابی.</h2><p>ماده، آدم‌ها، ابزار و محصول؛<br />یک زنجیرهٔ به‌هم‌پیوسته.</p><button onClick={() => open("batch", state.batches[0]?.id)}>دیدن یک پرونده <ArrowUpLeft size={17} /></button><div className="bullion-art" aria-hidden="true"><div className="art-ring ring-one" /><div className="art-ring ring-two" /><div className="bullion silver-bar"><b>M</b><small>MORIYATI</small><span>FINE SILVER</span><strong>999.9</strong></div><div className="bullion gold-bar"><b>M</b><small>MORIYATI</small><span>FINE GOLD</span><strong>995.0</strong></div></div></section></div>
        <div className="dashboard-bottom"><section className="panel batches-panel"><div className="panel-heading"><div><h2>بچ‌های در جریان</h2><p>وضعیت فعلی، مسئول کار و مسیر هر محموله</p></div><button className="text-button" onClick={() => go("batches")}>همهٔ بچ‌ها <ArrowLeft size={15} /></button></div>{batchTable(active.slice(0, 4))}</section><section className="panel activity-panel"><div className="panel-heading"><h2>آخرین رویدادها</h2><History size={17} /></div>{eventList(state.logs, 4)}</section></div>
        {low.length > 0 && <div className="inventory-reminder"><span className="reminder-icon"><TriangleAlert size={19} /></span><div><b>{n(low.length)} قلم به بررسی موجودی نیاز دارد</b><p>{low.map(i => i.name).join("، ")}</p></div><button className="text-button" onClick={() => go("inventory")}>بررسی انبار <ArrowLeft size={16} /></button></div>}
      </>}

      {page === "batches" && <section className="panel"><div className="list-toolbar"><Tabs values={["همه", "در جریان", "تکمیل‌شده", "طلا", "نقره"]} current={filter} onChange={setFilter} /><span className="list-count">{n(state.batches.length)} بچ ثبت‌شده</span></div>{!['همه', 'در جریان', 'تکمیل‌شده', 'طلا', 'نقره'].includes(filter) && <div className="active-filter"><Badge tone="blue">{filter}</Badge><button className="text-button" onClick={() => setFilter("همه")}>حذف فیلتر <X size={14} /></button></div>}{batchTable(state.batches.filter(b => filter === "همه" || filter === "در جریان" && b.stage < 5 || filter === "تکمیل‌شده" && b.stage === 5 || filter === metalName(b.metal) || filter === stages[b.stage]))}<div className="table-foot"><ShieldCheck size={14} />تمام تغییر مراحل و فعالیت افراد در سابقهٔ بچ ثبت می‌شوند.</div></section>}

      {page === "inventory" && <>
        <div className="stats-grid three"><Stat label="نقرهٔ آزاد در انبار" value={n(state.inventory.filter(i => i.metal === "silver").reduce((s, i) => s + fine(i.quantity, i.assay || 0), 0) / 1000, 3)} unit="کیلوگرم خالص" icon={<Gem size={19} />} note="جدا از مواد در جریان و محصولات سریال‌دار" /><Stat label="طلای آزاد در انبار" value={n(state.inventory.filter(i => i.metal === "gold").reduce((s, i) => s + fine(i.quantity, i.assay || 0), 0), 2)} unit="گرم خالص" icon={<Gem size={19} />} note="جدا از مواد در جریان و محصولات سریال‌دار" gold /><Stat label="اقلام نیازمند بررسی" value={n(low.length)} unit="قلم" icon={<TriangleAlert size={19} />} note="موجودی کمتر از حد سفارش یا منفی" /></div>
        <section className="panel"><div className="list-toolbar"><Tabs values={["همه", "فلز گرانبها", "مواد شیمیایی", "بسته‌بندی", "ملزومات", "نیازمند بررسی"]} current={filter} onChange={setFilter} /><button className="icon-btn" aria-label="دریافت فایل موجودی" onClick={() => csv("moriyati-inventory.csv", [["شناسه", "نام", "موجودی", "واحد", "حد سفارش"], ...state.inventory.map(i => [i.id, i.name, i.quantity, i.unit, i.minimum])])}><Download size={17} /></button></div><div className="table-scroll"><table><thead><tr><th>نام کالا</th><th>گروه</th><th>موجودی فعلی</th><th>حد سفارش</th><th>وضعیت</th><th /></tr></thead><tbody>{state.inventory.filter(i => filter === "همه" || filter === i.category || filter === "نیازمند بررسی" && i.quantity < i.minimum).map(i => <tr key={i.id}><td><div className="item-name"><span className={`item-symbol ${i.metal || "chemical"}`}>{i.metal ? <Gem size={18} /> : i.category === "مواد شیمیایی" ? <FlaskConical size={18} /> : <Package size={18} />}</span><span><b>{i.name}</b><small className="mono">{i.id}</small></span></div></td><td>{i.category}</td><td><strong className={i.quantity < 0 ? "danger-text" : "numeric"}>{n(i.quantity)}</strong> <span className="muted">{i.unit}</span></td><td>{n(i.minimum)} <span className="muted">{i.unit}</span></td><td><Badge tone={i.quantity < 0 ? "red" : i.quantity < i.minimum ? "amber" : "green"}>{i.quantity < 0 ? "موجودی منفی" : i.quantity < i.minimum ? "کمتر از حد سفارش" : "موجود"}</Badge></td><td><button className="text-button" onClick={() => open("inventory_move", i.id)}>ثبت گردش <Plus size={14} /></button></td></tr>)}</tbody></table></div><div className="table-foot"><TriangleAlert size={15} />مصرف بیش از موجودی ثبت می‌شود و هشدار اصلاح موجودی ایجاد می‌کند.</div></section>
        <section className="panel spaced"><div className="panel-heading"><h2>گردش‌های اخیر</h2><span className="muted">ورود، مصرف و اصلاح</span></div>{state.movements.length ? <div className="table-scroll"><table><thead><tr><th>کالا</th><th>تغییر موجودی</th><th>بچ مرتبط</th><th>شرح</th><th>زمان</th></tr></thead><tbody>{state.movements.slice(0, 20).map(m => <tr key={m.id}><td>{state.inventory.find(i => i.id === m.materialId)?.name}</td><td className={m.delta < 0 ? "danger-text" : "green-text"}>{m.delta > 0 ? "+" : ""}{n(m.delta)}</td><td><button className="text-button mono" onClick={() => m.batchId && open("batch", m.batchId)}>{m.batchId || "—"}</button></td><td>{m.note}</td><td>{date(m.time)}، {time(m.time)}</td></tr>)}</tbody></table></div> : <Empty title="گردشی ثبت نکرده‌ای" text="از «ثبت گردش»، ورود، مصرف یا اصلاح موجودی را امتحان کن." />}</section>
      </>}

      {page === "assets" && <><div className="info-strip"><Radio size={20} /><p>تجهیزات و ابزارهای معمول: <b>پلاک استیل + تگ RFID</b><span>ابزار در معرض حرارت: شناسهٔ سازمانی بدون تگ در ناحیهٔ داغ</span></p><Badge tone="neutral">ثبت شناسه فعال · اتصال خوانشگر در انتظار</Badge></div><div className="list-toolbar no-panel"><Tabs values={["همه", "فعال", "از چرخه خارج", "بوته", "قالب", "تجهیزات"]} current={filter} onChange={setFilter} /><span className="list-count">{n(state.assets.length)} شناسنامهٔ ابزار</span></div><div className="asset-grid">{state.assets.filter(a => filter === "همه" || filter === "فعال" && a.status === "active" || filter === "از چرخه خارج" && a.status === "retired" || filter === a.kind).map(a => <article className={`asset-card panel ${a.status === "retired" ? "retired" : ""}`} key={a.id}><div className="asset-card-head"><span className="asset-symbol">{a.kind === "بوته" ? <FlaskConical size={25} /> : <Wrench size={25} />}</span><Badge tone={a.status === "retired" ? "neutral" : a.maxCycles && a.cycles >= a.maxCycles ? "amber" : "green"}>{a.status === "retired" ? "خارج از چرخه" : a.cycles === 0 ? "نو · آمادهٔ استفاده" : "فعال"}</Badge></div><button className="asset-title" onClick={() => open("asset", a.id)}>{a.name}</button><p className="mono asset-tag">{a.id}</p><div className="asset-metrics"><div><strong>{n(a.cycles)}</strong><span>بار استفاده</span></div><div><strong>{n(a.grams / 1000, 2)}</strong><span>کیلوگرم پردازش</span></div></div><div className="asset-life"><span>آستانهٔ بازبینی</span><b>{a.maxCycles ? `${n(a.cycles)} از ${n(a.maxCycles)} بار` : "تعریف نشده"}</b></div><div className="progress-track"><span style={{ width: `${a.maxCycles ? Math.min(100, a.cycles / a.maxCycles * 100) : 0}%` }} /></div><div className="asset-label"><Radio size={14} /><span>{a.heat ? "شناسهٔ بدون تگ در ناحیهٔ داغ" : "پلاک استیل + شناسهٔ RFID"}</span><b className="mono">{a.tag}</b></div>{a.reason && <p className="retired-reason">علت خروج: {a.reason}</p>}<div className="asset-actions">{a.status === "active" && <button className="text-button" onClick={() => open("use_asset", a.id)}>ثبت کارکرد <Plus size={14} /></button>}<button className="text-button muted" onClick={() => open("asset", a.id)}>پروندهٔ ابزار <ArrowLeft size={14} /></button></div></article>)}</div></>}

      {page === "products" && <><div className="collection-strip">{collections.map(c => <button key={c.name} className={filter === c.name ? "active" : ""} onClick={() => setFilter(filter === c.name ? "همه" : c.name)}><span>{c.name}</span><small>{c.fa}</small></button>)}</div><section className="panel"><div className="panel-heading"><h2>شناسنامه‌های ثبت‌شده</h2><Badge tone="neutral">{n(state.products.length)} محصول</Badge></div><div className="product-grid">{state.products.filter(p => filter === "همه" || p.collection === filter).map(p => <button className="product-card" key={p.id} onClick={() => open("product", p.id)}><div className={`product-visual ${p.metal}`}>{p.front ? <img src={p.front} alt={`نمای روی ${p.serial}`} /> : <div className="product-ingot"><b>M</b><span>MORIYATI</span><small>{p.collection}</small><strong>{n(p.weight)} g</strong><em>{p.assay.toFixed(1)}</em></div>}<Badge tone="neutral">{p.front ? "عکس ثبت‌شده" : "نمای نمادین"}</Badge></div><div className="product-card-body"><div><h3>{p.collection}</h3><ArrowUpLeft size={19} /></div><span className="mono">{p.serial}</span><p>{n(p.weight)} گرم {metalName(p.metal)} <span>عیار {p.assay.toFixed(1)}</span></p><div className="product-card-foot"><Fingerprint size={15} /><span>متصل به بچ و بسته‌بندی</span><Check size={14} /></div></div></button>)}</div>{!state.products.some(p => filter === "همه" || p.collection === filter) && <Empty title="هنوز محصولی در این مجموعه ثبت نشده" text="برای ثبت محصول، بچ باید کنترل کیفیت را گذرانده باشد." />}<div className="table-foot"><ShieldCheck size={15} />این صفحه شناسنامهٔ داخلی است. اعتبارسنجی رمزنگاری NFC و صفحهٔ عمومی مشتری هنوز متصل نیست.</div></section></>}

      {page === "team" && <><div className="info-strip"><Users size={21} /><p><b>فهرست همکاران و ثبت نقش در بچ</b><span>در این نسخه، مدیر می‌تواند فعالیت افراد نمونه را ثبت کند. حساب مستقل و سطح دسترسی کارکنان هنوز فعال نیست.</span></p></div><div className="team-grid">{state.operators.map(o => { const b = state.batches.find(b => b.sessions.some(s => s.operatorId === o.id && !s.end)); const sessions = state.batches.flatMap(b => b.sessions).filter(s => s.operatorId === o.id); return <article className="panel team-card" key={o.id}><span className="large-avatar">{o.initials}</span><Badge tone={b ? "green" : "neutral"}>{b ? "مشغول به کار" : "آمادهٔ کار"}</Badge><h3>{o.name}</h3><p>{o.role}</p><div className="team-meta"><span>شناسهٔ سازمانی</span><b className="mono">{o.id}</b></div><div className="team-meta"><span>فعالیت ثبت‌شده</span><b>{n(sessions.length)} مرتبه</b></div>{b ? <button className="assigned-batch" onClick={() => open("batch", b.id)}><i className="status-dot" /><span className="mono">{b.id}</span><ArrowLeft size={15} /></button> : <div className="no-assignment">در حال حاضر کار بازی ندارد</div>}</article>; })}</div></>}

      {page === "reports" && <><div className="report-intro"><ShieldCheck size={24} /><div><h2>تراز فلز، بر مبنای خلوص.</h2><p>ورودی خالص = وزن ورودی × عیار ÷ ۱۰۰۰. «اختلاف» ماندهٔ حساب‌نشده است و تا بررسی، افت قطعی محسوب نمی‌شود.</p></div></div>{["silver", "gold"].map(m => { const done = state.batches.filter(b => b.metal === m && b.stage === 5); const totals = done.reduce((s, b) => { const x = massBalance(b); return { incoming: s.incoming + x.incoming, outgoing: s.outgoing + x.outgoing, recoverable: s.recoverable + x.recoverable, difference: s.difference + x.difference }; }, { incoming: 0, outgoing: 0, recoverable: 0, difference: 0 }); return <section className="panel spaced" key={m}><div className="panel-heading"><h2 className="flex"><MetalDot metal={m as Metal} />تراز بچ‌های تکمیل‌شدهٔ {metalName(m as Metal)}</h2><Badge tone="neutral">{n(done.length)} بچ</Badge></div><div className="balance-grid"><div><span>ورودی خالص</span><strong>{n(totals.incoming, 3)} <small>گرم</small></strong></div><div><span>خروجی خالص</span><strong>{n(totals.outgoing, 3)} <small>گرم</small></strong></div><div><span>قابل بازیافت</span><strong>{n(totals.recoverable, 3)} <small>گرم</small></strong></div><div><span>اختلاف نیازمند بررسی</span><strong className={totals.difference > 0 ? "amber-text" : ""}>{n(totals.difference, 3)} <small>گرم</small></strong></div></div>{done.length ? <div className="table-scroll"><table><thead><tr><th>بچ</th><th>ورودی خالص / گرم</th><th>خروجی خالص / گرم</th><th>قابل بازیافت / گرم</th><th>اختلاف / گرم</th><th>بازیابی محصول</th></tr></thead><tbody>{done.map(b => { const x = massBalance(b); return <tr key={b.id}><td><button className="text-button mono" onClick={() => open("batch", b.id)}>{b.id}</button></td><td>{n(x.incoming, 3)}</td><td>{n(x.outgoing, 3)}</td><td>{n(x.recoverable, 3)}</td><td className="amber-text">{n(x.difference, 3)}</td><td>{n(x.recovery, 3)}٪</td></tr>; })}</tbody></table></div> : <Empty title="بچ تکمیل‌شده‌ای برای این فلز وجود ندارد" text="پس از ثبت وزن خروجی در کنترل کیفیت، تراز نمایش داده می‌شود." />}</section>; })}<section className="panel spaced"><div className="panel-heading"><h2>دفتر رویدادهای عملیات</h2><button className="text-button" onClick={() => csv("moriyati-events.csv", [["زمان", "نوع", "شرح", "بچ", "ثبت‌کننده"], ...state.logs.map(l => [l.time, l.type, l.text, l.batchId || "", l.actor])])}>خروجی رویدادها <Download size={15} /></button></div>{eventList(state.logs, 30)}</section></>}

      {page === "connections" && <><div className="connection-grid">{[{ icon: ShieldCheck, title: "فضای خصوصی و پایگاه داده", text: "بچ‌ها، گردش‌ها و رویدادها بین دستگاه‌های همین حساب همگام می‌شوند.", status: mode === "cloud" ? "متصل" : "در انتظار اتصال", connected: mode === "cloud" }, { icon: Link2, title: "مخزن GitHub", text: "کد این نسخه در شاخهٔ moriyati-erp از مخزن موریاتی نگهداری می‌شود.", status: "مشاهدهٔ کد", href: "https://github.com/moriyati-ir/moriyati.ir/tree/moriyati-erp/erp" }, { icon: Boxes, title: "حسابداری زرین", text: "برای اتصال، مستندات API و دسترسی سرویس لازم است.", status: "هنوز متصل نیست" }, { icon: Radio, title: "خوانشگر RFID / NFC", text: "ثبت دستی شناسه فعال است؛ اتصال خوانشگر و اعتبارسنجی رمزنگاری در مرحلهٔ بعد.", status: "هنوز متصل نیست" }, { icon: Fingerprint, title: "سایت و اصالت‌سنجی مشتری", text: "شناسنامهٔ داخلی آماده است؛ انتشار صفحهٔ مشتری روی moriyati.ir نیازمند اتصال است.", status: "هنوز متصل نیست" }, { icon: Users, title: "حساب کارکنان و دسترسی‌ها", text: "این نسخه برای بررسی مدیر است؛ دعوت کارکنان و مجوزهای نقش‌ها هنوز فعال نیست.", status: "در مرحلهٔ بعد" }].map(c => <article className="panel connection-card" key={c.title}><span className="connection-icon"><c.icon size={25} /></span><h3>{c.title}</h3><p>{c.text}</p>{c.href ? <a className="text-button" href={c.href} target="_blank" rel="noreferrer">{c.status}<ArrowUpLeft size={15} /></a> : <Badge tone={c.connected ? "green" : "neutral"}>{c.status}</Badge>}</article>)}</div><div className="info-strip spaced"><CircleHelp size={21} /><p><b>نسخهٔ قابل بررسی، برای شکل دادن به فرایند واقعی کارخانه</b><span>اتصال ترازو، حسابداری، ثبت آفلاین و پشتیبان‌گیری مستقل هنوز پیاده‌سازی نشده‌اند. این نسخه جایگزین دفتر رسمی تولید یا حسابداری نیست.</span></p></div></>}

      <footer className="page-footer"><span>MORIYATI <i>ERP</i></span><span>شفافیت در هر مرحله. دقت در هر گرم.</span><span className="mono">PROTOTYPE / 0.1</span></footer>
    </main></div>

    <nav className="mobile-bottom" aria-label="دسترسی سریع">{nav.slice(0, 5).map(i => <button key={i.id} className={page === i.id ? "selected" : ""} onClick={() => go(i.id)}><i.icon size={20} /><span>{i.label}</span></button>)}</nav>
    {toast && <div className={`toast ${toast.error ? "error" : ""}`} role="status">{toast.error ? <TriangleAlert size={20} /> : <CheckCheck size={20} />}<span>{toast.text}</span><button className="icon-btn" aria-label="بستن پیام" onClick={() => setToast(null)}><X size={16} /></button></div>}

    {modal?.kind === "alerts" && <Dialog title="موارد نیازمند توجه" subtitle="هشدارها ثبت عملیات را متوقف نمی‌کنند." onClose={close}><div className="dialog-body">{low.map(i => <div className="alert-row" key={i.id}><TriangleAlert size={20} /><div><b>{i.name}</b><p>موجودی {n(i.quantity)} {i.unit} · حد سفارش {n(i.minimum)}</p></div><button className="text-button" onClick={() => open("inventory_move", i.id)}>اصلاح / ورود</button></div>)}{!low.length && <Empty title="هشدار موجودی فعالی وجود ندارد" text="موجودی تمام اقلام در محدودهٔ تعریف‌شده است." />}</div></Dialog>}

    {modal?.kind === "batch" && selectedBatch && <Dialog wide title={`پروندهٔ بچ ${selectedBatch.id}`} subtitle={`${selectedBatch.owner} · ${selectedBatch.source}`} onClose={close}><div className="dialog-body batch-detail"><div className="detail-top"><Badge tone="blue">{stages[selectedBatch.stage]}</Badge><span>{date(selectedBatch.created)} · {time(selectedBatch.created)}</span>{selectedBatch.priority === "فوری" && <Badge tone="amber">اولویت فوری</Badge>}</div><div className="detail-stats"><div><span>فلز</span><strong>{metalName(selectedBatch.metal)}</strong></div><div><span>وزن ورودی</span><strong>{n(selectedBatch.weight)} <small>گرم</small></strong></div><div><span>عیار ورودی</span><strong className="mono">{selectedBatch.assay.toFixed(1)}</strong></div><div><span>فلز خالص ورودی</span><strong>{n(fine(selectedBatch.weight, selectedBatch.assay), 3)} <small>گرم</small></strong></div></div><div className="stage-track">{stages.map((s, i) => <div className={`${i < selectedBatch.stage ? "done" : ""} ${i === selectedBatch.stage ? "current" : ""}`} key={s}><span>{i < selectedBatch.stage ? <Check size={14} /> : n(i + 1)}</span><small>{s}</small></div>)}</div><div className="section-heading"><h3>افراد و زمان کار در این بچ</h3>{selectedBatch.stage < 5 && <button className="button small secondary" onClick={() => open("start_session", selectedBatch.id)}><Plus size={14} />شروع کار یک نفر</button>}</div><div className="session-list">{selectedBatch.sessions.map(s => <div className="session-row" key={s.id}><span className="mini-avatar">{state.operators.find(o => o.id === s.operatorId)?.initials}</span><div><b>{state.operators.find(o => o.id === s.operatorId)?.name}</b><small>{s.role} · {stages[s.stage]}</small></div><div className="session-times"><span>شروع {date(s.start)}، {time(s.start)}</span><small>{s.end ? `پایان ${date(s.end)}، ${time(s.end)}` : "در حال انجام"}</small></div><b className="session-duration"><Timer size={14} />{duration(s.start, s.end)}</b>{!s.end ? <button disabled={busy} className="button small secondary" onClick={() => send({ type: "end_session", data: { batchId: selectedBatch.id, sessionId: s.id } })}>پایان و تأیید</button> : <Badge>تأیید اپراتور</Badge>}</div>)}{!selectedBatch.sessions.length && <div className="inline-empty">هنوز کار فردی برای این بچ ثبت نشده است.</div>}</div><div className="section-heading"><h3>مصرف مواد و کارکرد ابزار</h3>{selectedBatch.stage < 5 && <div className="flex"><button className="text-button" onClick={() => open("batch_consumption", selectedBatch.id)}>مصرف مواد <Plus size={14} /></button><button className="text-button" onClick={() => open("batch_asset", selectedBatch.id)}>کارکرد ابزار <Plus size={14} /></button></div>}</div><div className="batch-linked">{state.movements.filter(m => m.batchId === selectedBatch.id).map(m => <div key={m.id}><FlaskConical size={16} /><span>{state.inventory.find(i => i.id === m.materialId)?.name}</span><b>{n(m.delta)} {state.inventory.find(i => i.id === m.materialId)?.unit}</b><small>{m.note}</small></div>)}{state.assetUses.filter(u => u.batchId === selectedBatch.id).map(u => <div key={u.id}><Wrench size={16} /><button className="text-button" onClick={() => open("asset", u.assetId)}>{state.assets.find(a => a.id === u.assetId)?.name}</button><b>{n(u.grams)} گرم</b><small>{state.operators.find(o => o.id === u.operatorId)?.name}</small></div>)}{!state.movements.some(m => m.batchId === selectedBatch.id) && !state.assetUses.some(u => u.batchId === selectedBatch.id) && <div className="inline-empty">مواد و ابزار استفاده‌شده را به همین بچ متصل کن.</div>}</div>{selectedBatch.note && <p className="batch-note">{selectedBatch.note}</p>}{selectedBatch.stage === 5 && <div className="balance-grid small-balance"><div><span>خروجی خالص</span><strong>{n(massBalance(selectedBatch).outgoing, 3)} <small>گرم</small></strong></div><div><span>قابل بازیافت</span><strong>{n(selectedBatch.recoverable || 0)} <small>گرم</small></strong></div><div><span>اختلاف نیازمند بررسی</span><strong>{n(massBalance(selectedBatch).difference, 3)} <small>گرم</small></strong></div></div>}<div className="section-heading"><h3>ردپای این بچ</h3><History size={17} /></div>{eventList(state.logs.filter(l => l.batchId === selectedBatch.id), 20)}{state.products.some(p => p.batchId === selectedBatch.id) && <div className="linked-products">{state.products.filter(p => p.batchId === selectedBatch.id).map(p => <button key={p.id} className="button secondary small mono" onClick={() => open("product", p.id)}><Fingerprint size={14} />{p.serial}<ArrowLeft size={14} /></button>)}</div>}</div><div className="dialog-actions"><button className="button secondary" onClick={close}>بستن پرونده</button>{selectedBatch.stage < 4 && <button disabled={busy} className="button primary" onClick={() => send({ type: "advance_batch", data: { batchId: selectedBatch.id } })}>انتقال به {stages[selectedBatch.stage + 1]}<ArrowLeft size={16} /></button>}{selectedBatch.stage === 4 && <button className="button primary" onClick={() => open("finalize_batch", selectedBatch.id)}><ShieldCheck size={16} />ثبت نتیجه و تکمیل بچ</button>}</div></Dialog>}

    {modal?.kind === "asset" && selectedAsset && <Dialog title={selectedAsset.name} subtitle={selectedAsset.id} onClose={close}><div className="dialog-body"><div className="detail-stats"><div><span>دفعات کارکرد</span><strong>{n(selectedAsset.cycles)}</strong></div><div><span>وزن پردازش‌شده</span><strong>{n(selectedAsset.grams / 1000)} <small>کیلوگرم</small></strong></div></div><div className="detail-line"><span>شناسهٔ سازمانی / تگ</span><b className="mono">{selectedAsset.tag}</b></div><div className="detail-line"><span>وضعیت</span><Badge tone={selectedAsset.status === "active" ? "green" : "neutral"}>{selectedAsset.status === "active" ? "فعال" : "خارج از چرخه"}</Badge></div>{selectedAsset.reason && <div className="info-strip">علت خروج: {selectedAsset.reason}</div>}<h3 className="subheading">بچ‌های مرتبط با کارکرد ثبت‌شده</h3>{state.assetUses.filter(u => u.assetId === selectedAsset.id).map(u => <button className="search-result" key={u.id} onClick={() => open("batch", u.batchId)}><span className="mono">{u.batchId}</span><span>{n(u.grams)} گرم</span><small>{date(u.time)}</small><ArrowLeft size={15} /></button>)}{!state.assetUses.some(u => u.assetId === selectedAsset.id) && <p className="muted">کارکرد قبلی این ابزار، مقدار اولیهٔ نمونه است. کارکردهای جدید با بچ و اپراتور ثبت می‌شوند.</p>}</div><div className="dialog-actions"><button className="button secondary" onClick={close}>بستن</button>{selectedAsset.status === "active" && <><button className="button danger" onClick={() => open("retire_asset", selectedAsset.id)}>خروج از چرخه</button><button className="button primary" onClick={() => open("use_asset", selectedAsset.id)}>ثبت کارکرد</button></>}</div></Dialog>}

    {modal?.kind === "product" && selectedProduct && <Dialog wide title="شناسنامهٔ محصول" subtitle={selectedProduct.serial} onClose={close}><div className="dialog-body product-detail"><div className="passport-heading"><span className="passport-seal"><Fingerprint size={38} /></span><div><span className="eyebrow">MORIYATI PRODUCT IDENTITY</span><h2>{selectedProduct.collection}</h2><span className="mono">{selectedProduct.serial}</span></div><Badge>شناسنامهٔ داخلی</Badge></div><div className="detail-stats"><div><span>فلز</span><strong>{metalName(selectedProduct.metal)}</strong></div><div><span>وزن</span><strong>{n(selectedProduct.weight)} <small>گرم</small></strong></div><div><span>عیار</span><strong className="mono">{selectedProduct.assay.toFixed(1)}</strong></div><div><span>تاریخ ثبت</span><strong>{date(selectedProduct.created)}</strong></div></div><div className="detail-line"><span>سریال بسته‌بندی</span><b className="mono">{selectedProduct.packaging}</b></div><div className="detail-line"><span>شناسهٔ NFC ثبت‌شده</span><b className="mono">{selectedProduct.nfc || "ثبت نشده"}</b></div><div className="detail-line"><span>بچ مبدأ</span><button className="text-button mono" onClick={() => open("batch", selectedProduct.batchId)}>{selectedProduct.batchId}<ArrowLeft size={14} /></button></div><div className="photo-grid">{(["front", "back"] as const).map(side => <div className="passport-photo" key={side}>{selectedProduct[side] ? <img src={selectedProduct[side]} alt={side === "front" ? "نمای روی محصول" : "نمای پشت محصول"} /> : <div><Package size={32} /><span>عکس {side === "front" ? "روی" : "پشت"} ثبت نشده</span></div>}</div>)}</div><div className="info-strip"><CircleHelp size={19} /><p>ثبت شناسهٔ تگ به معنای تأیید رمزنگاری آن نیست. اتصال به سامانهٔ اصالت‌سنجی مشتری در مرحلهٔ بعد انجام می‌شود.</p></div></div><div className="dialog-actions"><button className="button secondary" onClick={close}>بستن</button><button className="button primary" onClick={() => open("batch", selectedProduct.batchId)}>مشاهدهٔ زنجیرهٔ تولید <ArrowLeft size={16} /></button></div></Dialog>}

    {modal && !["alerts", "batch", "asset", "product"].includes(modal.kind) && <OperationForm key={`${modal.kind}-${modal.id || "new"}`} modal={modal} state={state} busy={busy} mode={mode} onClose={close} onSubmit={async command => { const ok = await send(command); if (ok) { const id = command.data.batchId as string; if (id && ["start_session", "finalize_batch", "batch_consumption", "batch_asset"].includes(modal.kind)) open("batch", id); else close(); } return ok; }} notify={notify} />}
  </div>;
}

function Stat({ label, value, unit, icon, note, gold, onClick }: { label: string; value: string; unit: string; icon: ReactNode; note: string; gold?: boolean; onClick?: () => void }) { return <button className={`stat-card ${gold ? "gold-stat" : ""}`} onClick={onClick} disabled={!onClick}><div className="stat-top"><span>{label}</span><span className="stat-icon">{icon}</span></div><div className="stat-value"><strong>{value}</strong><span>{unit}</span></div><div className="stat-note"><span className="tiny-line" />{note}{onClick && <ArrowUpLeft size={14} />}</div></button>; }
function Tabs({ values, current, onChange }: { values: string[]; current: string; onChange: (v: string) => void }) { return <div className="tabs" role="group" aria-label="فیلتر فهرست">{values.map(v => <button className={current === v ? "active" : ""} key={v} onClick={() => onChange(v)}>{v}</button>)}</div>; }

function OperationForm({ modal, state, busy, mode, onClose, onSubmit, notify }: { modal: NonNullable<Modal>; state: Workspace; busy: boolean; mode: string; onClose: () => void; onSubmit: (c: Command) => Promise<boolean>; notify: (text: string, error?: boolean) => void }) {
  const kind = modal.kind, batch = state.batches.find(b => b.id === modal.id), asset = state.assets.find(a => a.id === modal.id);
  const [values, setValues] = useState<Record<string, string>>({ metal: "silver", weight: "", assay: "999.9", priority: "عادی", source: "", owner: "", batchId: kind === "inventory_move" ? "" : batch?.id || (kind === "create_product" ? state.batches.find(b => b.stage === 5)?.id : state.batches.find(b => b.stage < 5)?.id) || "", operatorId: state.operators.find(o => !state.batches.some(b => b.sessions.some(s => s.operatorId === o.id && !s.end)))?.id || state.operators[0]?.id || "", role: "اپراتور " + stages[batch?.stage || 0], materialId: state.inventory.find(i => i.id === modal.id)?.id || state.inventory[0]?.id || "", operation: kind === "batch_consumption" ? "consume" : "receipt", note: "", quantity: "", kind: "بوته", name: "", tag: "", heat: "true", maxCycles: "25", replaces: "", reason: "", assetId: asset?.id || state.assets.find(a => a.status === "active")?.id || "", grams: batch ? String(batch.weight) : "", output: "", outputAssay: "999.9", recoverable: "0", collection: "Argentum", serial: "", packaging: "", nfc: "", front: "", back: "" });
  const [uploading, setUploading] = useState(false), [formError, setFormError] = useState("");
  const set = (key: string, value: string) => setValues(v => ({ ...v, [key]: value }));
  const input = (key: string, props: Record<string, unknown> = {}) => <input name={key} value={values[key] || ""} onChange={e => set(key, e.target.value)} required {...props} />;
  const select = (key: string, options: { value: string; label: string }[]) => <select name={key} value={values[key] || ""} onChange={e => set(key, e.target.value)} required>{options.map(o => <option value={o.value} key={o.value}>{o.label}</option>)}</select>;
  const batchSelect = (complete = false, optional = false) => <select value={values.batchId} onChange={e => { set("batchId", e.target.value); const b = state.batches.find(b => b.id === e.target.value); if (b) set("grams", String(b.weight)); }} required={!optional}>{optional && <option value="">بدون بچ مرتبط</option>}{state.batches.filter(b => complete ? b.stage === 5 : b.stage < 5).map(b => <option key={b.id} value={b.id}>{b.id} · {metalName(b.metal)} · {stages[b.stage]}</option>)}</select>;
  const titles: Record<string, string> = { create_batch: "دریافت محموله و ساخت بچ", inventory_move: "ثبت گردش انبار", batch_consumption: "ثبت مصرف مواد در بچ", create_asset: "ثبت ابزار و تجهیزات جدید", retire_asset: "خروج ابزار از چرخه", use_asset: "ثبت کارکرد ابزار", batch_asset: "ثبت کارکرد ابزار در بچ", start_session: "شروع کار در بچ", finalize_batch: "کنترل کیفیت و تکمیل بچ", create_product: "ثبت شناسنامهٔ محصول", create_operator: "افزودن همکار" };
  async function upload(file: File | undefined, side: string) {
    if (!file) return;
    if (mode !== "cloud") { notify("آپلود عکس به ورود و اتصال پایگاه داده نیاز دارد.", true); return; }
    setUploading(true);
    try { const data = new FormData(); data.set("file", file); const r = await fetch("/api/photos", { method: "POST", body: data }); const j = await r.json() as { error?: string; url: string }; if (!r.ok) throw new Error(j.error); set(side, j.url); }
    catch (e) { notify(e instanceof Error ? e.message : "آپلود انجام نشد.", true); }
    finally { setUploading(false); }
  }
  return <Dialog title={titles[kind] || "ثبت عملیات"} subtitle={batch ? `${batch.id} · ${stages[batch.stage]}` : asset?.name || "اطلاعات این نسخه در محیط آزمایشی ثبت می‌شود."} onClose={onClose}>
    <form onSubmit={async e => { e.preventDefault(); setFormError(""); const commandKind = kind === "batch_consumption" ? "inventory_move" : kind === "batch_asset" ? "use_asset" : kind; const data: Record<string, unknown> = { ...values, heat: values.heat === "true", assetId: asset?.id || values.assetId }; const ok = await onSubmit({ type: commandKind, data }); if (!ok) setFormError("ثبت انجام نشد؛ پیام خطا را بررسی کن."); }}>
    <div className="dialog-body"><div className="form-grid">
      {kind === "create_batch" && <><Field label="نوع فلز">{select("metal", [{ value: "silver", label: "نقره · Ag" }, { value: "gold", label: "طلا · Au" }])}</Field><Field label="اولویت">{select("priority", [{ value: "عادی", label: "عادی" }, { value: "فوری", label: "فوری" }])}</Field><Field label="شرح / مبدأ ورودی" wide>{input("source", { placeholder: "مثلاً نقرهٔ ورودی مشتری" })}</Field><Field label="مالک محموله" wide>{input("owner", { placeholder: "نام مالک یا موجودی موریاتی" })}</Field><Field label="وزن ناخالص ورودی (گرم)">{input("weight", { type: "number", min: "0.001", step: "any", dir: "ltr", placeholder: "40000" })}</Field><Field label="عیار ورودی (از ۱۰۰۰)">{input("assay", { type: "number", min: "0.001", max: "1000", step: "any", dir: "ltr" })}</Field><Field label="یادداشت" wide><textarea value={values.note} onChange={e => set("note", e.target.value)} rows={3} /></Field><div className="form-callout wide">ورود جدید مستقیماً در مواد در جریان این بچ ثبت می‌شود. وزن‌ها همیشه بر حسب گرم هستند.</div></>}
      {["inventory_move", "batch_consumption"].includes(kind) && <><Field label="کالا" wide>{select("materialId", state.inventory.map(i => ({ value: i.id, label: `${i.name} · موجودی ${n(i.quantity)} ${i.unit}` })))}</Field><Field label="نوع گردش">{select("operation", [{ value: "receipt", label: "ورود به انبار" }, { value: "consume", label: "مصرف / خروج" }, { value: "adjust", label: "اصلاح موجودی فعلی" }])}</Field><Field label={values.operation === "adjust" ? "موجودی صحیح فعلی" : `مقدار (${state.inventory.find(i => i.id === values.materialId)?.unit})`}>{input("quantity", { type: "number", step: "any", min: values.operation === "adjust" ? undefined : "0.001", dir: "ltr" })}</Field><Field label="بچ مرتبط" wide>{kind === "batch_consumption" ? <input readOnly value={values.batchId} dir="ltr" /> : batchSelect(false, true)}</Field><Field label="شرح و علت گردش" wide>{input("note", { placeholder: "علت مصرف، ورود یا اصلاح موجودی" })}</Field><div className="form-callout wide"><TriangleAlert size={17} />مصرف بیش از موجودی ثبت می‌شود؛ سامانه هشدار منفی شدن موجودی می‌دهد.</div></>}
      {kind === "start_session" && <><Field label="اپراتور" wide>{select("operatorId", state.operators.map(o => ({ value: o.id, label: `${o.name} · ${o.role}${state.batches.some(b => b.sessions.some(s => s.operatorId === o.id && !s.end)) ? " (کار باز دارد)" : ""}` })))}</Field><Field label="نقش این نفر در این بچ" wide>{input("role", { placeholder: "مثلاً مسئول ذوب یا کمک اپراتور" })}</Field><div className="form-callout wide"><Timer size={18} />زمان شروع هنگام ثبت ذخیره می‌شود. پایان کار با تأیید خود اپراتور ثبت خواهد شد.</div></>}
      {kind === "finalize_batch" && <><Field label="وزن واقعی خروجی (گرم)">{input("output", { type: "number", min: "0.001", step: "any", dir: "ltr" })}</Field><Field label="عیار واقعی خروجی">{input("outputAssay", { type: "number", min: "0.001", max: "1000", step: "any", dir: "ltr" })}</Field><Field label="فلز خالص قابل بازیافت (گرم)" wide>{input("recoverable", { type: "number", min: "0", step: "any", dir: "ltr" })}</Field><div className="form-callout wide">ورودی خالص این بچ: <b>{n(fine(batch!.weight, batch!.assay), 3)} گرم</b>. خروجی تأییدشده به انبار اضافه می‌شود.</div>{values.output && <div className="form-callout wide">اختلاف برای بررسی: {n(fine(batch!.weight, batch!.assay) - fine(Number(values.output), Number(values.outputAssay)) - Number(values.recoverable), 3)} گرم فلز خالص</div>}</>}
      {kind === "create_asset" && <><Field label="نام ابزار" wide>{input("name", { placeholder: "مثلاً بوته گرافیتی شماره ۳" })}</Field><Field label="نوع ابزار">{select("kind", ["بوته", "قالب", "تجهیزات", "ابزار"].map(x => ({ value: x, label: x })))}</Field><Field label="آستانهٔ بازبینی (دفعات)">{input("maxCycles", { type: "number", min: "0", step: "1", dir: "ltr" })}</Field><Field label="شیوهٔ شناسایی" wide>{select("heat", [{ value: "true", label: "در معرض حرارت · شناسهٔ سازمانی بدون تگ در ناحیهٔ داغ" }, { value: "false", label: "پلاک استیل + شناسهٔ تگ RFID" }])}</Field><Field label="شناسهٔ یکتا / شناسهٔ تگ" wide>{input("tag", { dir: "ltr", placeholder: values.heat === "true" ? "CR-003" : "RFID-..." })}</Field><Field label="این ابزار جایگزین کدام ابزار می‌شود؟" wide>{select("replaces", [{ value: "", label: "افزایش ظرفیت / ابزار جدید؛ جایگزینی نیست" }, ...state.assets.filter(a => a.status === "active" && a.kind === values.kind).map(a => ({ value: a.id, label: `${a.name} · ${n(a.cycles)} بار کارکرد` }))])}</Field>{values.replaces && <><Field label="علت خروج ابزار قبلی" wide>{input("reason", { placeholder: "شکستگی، ترک یا فرسودگی..." })}</Field><div className="form-callout wide">با ثبت، ابزار قبلی از چرخه خارج و سابقهٔ جایگزینی حفظ می‌شود.</div></>}</>}
      {kind === "retire_asset" && <><div className="form-callout wide">این ابزار {n(asset?.cycles || 0)} بار استفاده شده و {n((asset?.grams || 0) / 1000)} کیلوگرم پردازش ثبت‌شده دارد. سابقهٔ آن حفظ می‌شود.</div><Field label="علت غیرقابل‌استفاده شدن" wide>{input("reason", { placeholder: "مثلاً ترک بدنه یا فرسودگی" })}</Field></>}
      {["use_asset", "batch_asset"].includes(kind) && <><Field label="ابزار" wide>{asset ? <input readOnly value={asset.name} /> : select("assetId", state.assets.filter(a => a.status === "active").map(a => ({ value: a.id, label: `${a.name} · ${a.id}` })))}</Field><Field label="بچ مرتبط" wide>{batchSelect()}</Field><Field label="اپراتور">{select("operatorId", state.operators.map(o => ({ value: o.id, label: o.name })))}</Field><Field label="وزن این نوبت پردازش (گرم)">{input("grams", { type: "number", min: "0.001", step: "any", dir: "ltr" })}</Field><div className="form-callout wide">هر ثبت، یک نوبت کارکرد به ابزار اضافه می‌کند؛ وزن پردازش نیز به کارکرد تجمعی افزوده می‌شود.</div></>}
      {kind === "create_product" && <><Field label="مجموعه" wide><select value={values.collection} onChange={e => { set("collection", e.target.value); const c = collections.find(c => c.name === e.target.value)!; set("weight", String(c.weights[0])); set("assay", String(c.assay)); }} required>{collections.map(c => <option key={c.name} value={c.name}>{c.name} · {c.fa}</option>)}</select></Field><Field label="بچ مبدأ تکمیل‌شده" wide>{batchSelect(true)}</Field><Field label="وزن (گرم)">{select("weight", [{ value: "", label: "انتخاب وزن" }, ...(collections.find(c => c.name === values.collection)?.weights || []).map(w => ({ value: String(w), label: w === 31.1034768 ? "۱ اونس تروا · ۳۱٫۱۰۳۴۷۶۸ گرم" : `${n(w)} گرم` }))])}</Field><Field label="عیار">{values.collection === "Argentum" ? select("assay", [{ value: "999.9", label: "999.9" }, { value: "995", label: "995.0" }]) : <input readOnly value={collections.find(c => c.name === values.collection)?.assay.toFixed(1)} dir="ltr" />}</Field><Field label="سریال یکتای محصول">{input("serial", { dir: "ltr", placeholder: "MOR-AG-000003", maxLength: 100 })}</Field><Field label="سریال یکتای بسته‌بندی">{input("packaging", { dir: "ltr", placeholder: "PKG-000003", maxLength: 100 })}</Field><Field label="شناسهٔ تگ NFC (اختیاری)" wide>{input("nfc", { dir: "ltr", required: false, maxLength: 100 })}</Field>{["front", "back"].map(side => <Field label={`عکس ${side === "front" ? "روی" : "پشت"} محصول`} key={side} hint="JPG، PNG، WebP · حداکثر ۵ مگابایت"><span className={`upload-box ${values[side] ? "uploaded" : ""}`}>{values[side] ? <><CheckCheck size={20} />عکس آماده است</> : <><Plus size={20} />انتخاب عکس</>}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading || mode !== "cloud"} onChange={e => upload(e.target.files?.[0], side)} /></span></Field>)}<div className="form-callout wide">فلز و عیار باید با خروجی بچ یکسان باشند. وزن محصول از موجودی آزاد انبار به موجودی محصولات سریال‌دار منتقل می‌شود.</div></>}
      {kind === "create_operator" && <><Field label="نام همکار" wide>{input("name")}</Field><Field label="مسئولیت / تخصص" wide>{input("role", { placeholder: "مثلاً اپراتور پالایش" })}</Field><div className="form-callout wide">این کار فقط همکار را به فهرست عملیات اضافه می‌کند. حساب ورود مستقل ایجاد نمی‌شود.</div></>}
    </div>{formError && <p className="error-box" role="alert">{formError}</p>}</div><div className="dialog-actions"><button type="button" className="button secondary" onClick={onClose}>انصراف</button><button className={`button ${kind === "retire_asset" ? "danger" : "primary"}`} disabled={busy || uploading} type="submit">{busy || uploading ? <Loader2 className="spin" size={17} /> : <Check size={17} />}{uploading ? "در حال بارگذاری عکس..." : busy ? "در حال ثبت..." : kind === "start_session" ? "ثبت شروع کار" : kind === "retire_asset" ? "ثبت خروج از چرخه" : "ثبت اطلاعات"}</button></div>
    </form>
  </Dialog>;
}
